BEGIN;
SET LOCAL lock_timeout='15s';
SET LOCAL statement_timeout='10min';
SELECT pg_advisory_xact_lock(hashtextextended('CropQc:20260823040226_AddActualRunSalesDeskAttribution',0));
SELECT to_regclass(format('%I.%I',current_schema(),'SalesDesks')) IS NULL AS create_target \gset
\if :create_target
CREATE TABLE "SalesDesks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "IsActive" boolean NOT NULL,
    "DisplayOrder" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedByUserId" integer,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedByUserId" integer,
    CONSTRAINT "PK_SalesDesks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SalesDesks_Users_CreatedByUserId" FOREIGN KEY ("CreatedByUserId") REFERENCES "Users"("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_SalesDesks_Users_UpdatedByUserId" FOREIGN KEY ("UpdatedByUserId") REFERENCES "Users"("Id") ON DELETE SET NULL
);
ALTER TABLE "ActualRuns" ADD COLUMN "SalesDeskId" integer;
ALTER TABLE "ActualRuns" ADD COLUMN "SalesDeskNameSnapshot" character varying(100);
ALTER TABLE "ActualRunOverrideRequests" ADD COLUMN "SalesDeskId" integer;
ALTER TABLE "ActualRunOverrideRequests" ADD COLUMN "SalesDeskNameSnapshot" character varying(100);
CREATE TABLE "ActualRunSalesDeskCorrections" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ActualRunId" bigint NOT NULL,
    "OperationKey" character varying(64) NOT NULL,
    "ExpectedConcurrencyVersion" bigint NOT NULL,
    "PreviousSalesDeskId" integer,
    "PreviousSalesDeskNameSnapshot" character varying(100),
    "NewSalesDeskId" integer NOT NULL,
    "NewSalesDeskNameSnapshot" character varying(100) NOT NULL,
    "Reason" character varying(1000) NOT NULL,
    "CorrectedByUserId" integer NOT NULL,
    "CorrectedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ActualRunSalesDeskCorrections" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ActualRunSalesDeskCorrections_ActualRuns_ActualRunId" FOREIGN KEY ("ActualRunId") REFERENCES "ActualRuns"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ActualRunSalesDeskCorrections_SalesDesks_NewSalesDeskId" FOREIGN KEY ("NewSalesDeskId") REFERENCES "SalesDesks"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ActualRunSalesDeskCorrections_SalesDesks_PreviousSalesDeskId" FOREIGN KEY ("PreviousSalesDeskId") REFERENCES "SalesDesks"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ActualRunSalesDeskCorrections_Users_CorrectedByUserId" FOREIGN KEY ("CorrectedByUserId") REFERENCES "Users"("Id") ON DELETE RESTRICT
);
INSERT INTO "SalesDesks" ("Id","Name","IsActive","DisplayOrder","CreatedAt","UpdatedAt") VALUES
