    (3,'Viva Tierra',true,30,'2026-05-21T00:00:00Z','2026-05-21T00:00:00Z');
SELECT setval(pg_get_serial_sequence('"SalesDesks"','Id'), GREATEST((SELECT max("Id") FROM "SalesDesks"),1), true);
CREATE INDEX "IX_ActualRuns_SalesDeskId_Status_RunAt" ON "ActualRuns"("SalesDeskId","Status","RunAt");
CREATE INDEX "IX_ActualRunOverrideRequests_SalesDeskId" ON "ActualRunOverrideRequests"("SalesDeskId");
CREATE INDEX "IX_ActualRunSalesDeskCorrections_ActualRunId_CorrectedAt" ON "ActualRunSalesDeskCorrections"("ActualRunId","CorrectedAt");
CREATE INDEX "IX_ActualRunSalesDeskCorrections_CorrectedByUserId" ON "ActualRunSalesDeskCorrections"("CorrectedByUserId");
CREATE INDEX "IX_ActualRunSalesDeskCorrections_NewSalesDeskId" ON "ActualRunSalesDeskCorrections"("NewSalesDeskId");
CREATE UNIQUE INDEX "IX_ActualRunSalesDeskCorrections_OperationKey" ON "ActualRunSalesDeskCorrections"("OperationKey");
CREATE INDEX "IX_ActualRunSalesDeskCorrections_PreviousSalesDeskId" ON "ActualRunSalesDeskCorrections"("PreviousSalesDeskId");
CREATE INDEX "IX_SalesDesks_CreatedByUserId" ON "SalesDesks"("CreatedByUserId");
CREATE INDEX "IX_SalesDesks_IsActive_DisplayOrder_Name" ON "SalesDesks"("IsActive","DisplayOrder","Name");
CREATE UNIQUE INDEX "IX_SalesDesks_Name" ON "SalesDesks"("Name");
CREATE INDEX "IX_SalesDesks_UpdatedByUserId" ON "SalesDesks"("UpdatedByUserId");
ALTER TABLE "ActualRuns" ADD CONSTRAINT "FK_ActualRuns_SalesDesks_SalesDeskId" FOREIGN KEY ("SalesDeskId") REFERENCES "SalesDesks"("Id") ON DELETE RESTRICT;
ALTER TABLE "ActualRunOverrideRequests" ADD CONSTRAINT "FK_ActualRunOverrideRequests_SalesDesks_SalesDeskId" FOREIGN KEY ("SalesDeskId") REFERENCES "SalesDesks"("Id") ON DELETE RESTRICT;
\else
\echo 'Actual Run Sales Desk schema is already complete and exact; no DDL or configuration writes will be applied.'
\endif
DO $postcheck$ BEGIN
    IF to_regclass(format('%I.%I',current_schema(),'SalesDesks')) IS NULL THEN RAISE EXCEPTION 'SalesDesks schema missing after apply'; END IF;
    IF current_setting('cropqc.test_force_sales_desk_failure',true)='on' THEN RAISE EXCEPTION 'Forced Sales Desk compatibility failure for rollback regression'; END IF;
